# ROOT is a sentinel object representing the root/target of the glom operation
class _RootSentinel:
    """Sentinel representing the root/target of the glom operation."""
    __slots__ = ()
    def __repr__(self):
        return 'ROOT'
    def __bool__(self):
        return True
    def __instancecheck__(self, instance):
        # Allow isinstance checks against subclasses
        return type(instance) is _RootSentinel or super().__instancecheck__(instance)
    def __reduce__(self):
        return ('ROOT', ())

ROOT = _RootSentinel()
